def _get_feat_extract_output_lengths(input_lengths, downsample_times=4, chunk_size=100):
    """
    Computes the output length of the convolutional layers and the output length of the audio encoder
    """

    input_lengths_leave = input_lengths % chunk_size
    for _ in range(downsample_times):
        input_lengths_leave = (input_lengths_leave - 1) // 2 + 1
    return input_lengths_leave + (input_lengths // chunk_size) * math.ceil(100 / 2**downsample_times)


class Qwen3_5OmniProcessor(ProcessorMixin):
    r"""
    Constructs a Qwen2.5Omni processor.
    [`Qwen3_5OmniProcessor`] offers all the functionalities of [`Qwen2VLImageProcessor`], [`WhisperFeatureExtractor`], and [`Qwen2TokenizerFast`]. See the
    [`~Qwen3_5OmniProcessor.__call__`] and [`~Qwen3_5OmniProcessor.decode`] for more information.

    Args:
        image_processor ([`Qwen2VLImageProcessor`], *optional*):
            The image processor.
        video_processor ([`Qwen2VLVideoProcessor`], *optional*):
            The video processor.
        feature_extractor ([`WhisperFeatureExtractor`], *optional*):
            The audio feature extractor.
        tokenizer ([`Qwen2TokenizerFast`], *optional*):
            The text tokenizer.
        chat_template (`Optional[str]`, *optional*):
            The Jinja template to use for formatting the conversation. If not provided, the default chat template is used.
    """

    attributes = ["image_processor", "video_processor", "feature_extractor", "tokenizer"]
    image_processor_class = "AutoImageProcessor"
    video_processor_class = "AutoVideoProcessor"
    feature_extractor_class = "WhisperFeatureExtractor"
    tokenizer_class = ("Qwen2Tokenizer", "Qwen2TokenizerFast")

    def __init__(
        self, image_processor=None, video_processor=None, feature_extractor=None, tokenizer=None, chat_template=None
    ):
        super().__init__(image_processor, video_processor, feature_extractor, tokenizer, chat_template=chat_template)
        self.image_token = self.tokenizer.image_token
        self.audio_token = self.tokenizer.audio_token
        self.video_token = self.tokenizer.video_token
        self.vision_bos_token = self.tokenizer.vision_bos_token
        self.vision_eos_token = self.tokenizer.vision_eos_token
        self.audio_bos_token = self.tokenizer.audio_bos_token
        self.audio_eos_token = self.tokenizer.audio_eos_token

        self.mm_token_pattern = re.compile(
            "|".join([re.escape(tok) for tok in [self.audio_token, self.image_token, self.video_token]])
        )

    def __call__(
        self,
        text: TextInput = None,
        images: ImageInput = None,
        videos: VideoInput = None,
        audio: AudioInput = None,
        **kwargs,
    ) -> BatchFeature:
        """
        Main method to prepare for the model one or several sequences(s) and audio(s). This method forwards the `text`
        and `kwargs` arguments to Qwen2TokenizerFast's [`~Qwen2TokenizerFast.__call__`] if `text` is not `None` to encode
        the text. To prepare the audio(s), this method forwards the `audio` and `kwargs` arguments to
        WhisperFeatureExtractor's [`~WhisperFeatureExtractor.__call__`] if `audio` is not `None`. To prepare the vision inputs,
        this method forwards the `vision_infos` and `kwargs` arguments to Qwen2VLImageProcessor's [`~Qwen2VLImageProcessor.__call__`]
        if `vision_infos` is not `None`. Please refer to the doctsring
        of the above two methods for more information.

        Args:
            text (`str`, `List[str]`, `List[List[str]]`):
                The sequence or batch of sequences to be encoded. Each sequence can be a string or a list of strings
                (pretokenized string). If the sequences are provided as list of strings (pretokenized), you must set
                `is_split_into_words=True` (to lift the ambiguity with a batch of sequences).
            images (`PIL.Image.Image`, `np.ndarray`, `torch.Tensor`, `List[PIL.Image.Image]`, `List[np.ndarray]`, `List[torch.Tensor]`):
                The image or batch of images to be prepared. Each image can be a PIL image, NumPy array or PyTorch
                tensor. Both channels-first and channels-last formats are supported.
            videos (`np.ndarray`, `torch.Tensor`, `List[np.ndarray]`, `List[torch.Tensor]`):
                The image or batch of videos to be prepared. Each video can be a 4D NumPy array or PyTorch
                tensor, or a nested list of 3D frames. Both channels-first and channels-last formats are supported.
            audio (`np.ndarray`, `List[np.ndarray]`):
                The audio or batch of audio to be prepared. Each audio can be a NumPy array.
        """

        if text is None:
            raise ValueError("You need to specify either a `text` input to process.")

        output_kwargs = self._merge_kwargs(
            Qwen3_5OmniProcessorKwargs,
            tokenizer_init_kwargs=self.tokenizer.init_kwargs,
            **kwargs,
        )

        # For vllm dummy
        if images is None and audio is None and videos is None:
            texts_inputs = self.tokenizer(text, **output_kwargs["text_kwargs"])

            return BatchFeature(
                data={
                    **texts_inputs,
                },
                tensor_type=kwargs.get("return_tensors"),
            )

        use_audio_in_video = output_kwargs["videos_kwargs"].pop("use_audio_in_video")
        if not isinstance(use_audio_in_video, list):
            use_audio_in_video = [use_audio_in_video] * (
                len(videos) if isinstance(videos, list) else int(videos is not None)
            )
        downsample_times = output_kwargs["audio_kwargs"].pop("downsample_times")
        downsample_chunk_size = output_kwargs["audio_kwargs"].pop("downsample_chunk_size")
        audio_timestamp_interval = output_kwargs["audio_kwargs"].pop("timestamp_interval")

        if audio is not None:
            # pad audio to be a multiple of sampling_rate
            padded_audios = []
            if not isinstance(audio, list):
                audio = [audio]
            for a in audio:
                padded_audios.append(
                    np.pad(
                        a,
                        (0, self.feature_extractor.sampling_rate - a.shape[-1] % self.feature_extractor.sampling_rate),
                    )
                )
            audio_inputs = self.feature_extractor(padded_audios, **output_kwargs["audio_kwargs"])
            audio_inputs["feature_attention_mask"] = audio_inputs.pop(
                "attention_mask"
            )  # rename feature_attention_mask to prevent conflicts later on
            audio_lengths = _get_feat_extract_output_lengths(
                audio_inputs["feature_attention_mask"].sum(-1),
                downsample_times,
                downsample_chunk_size,
            )
        else:
            audio_inputs = {}
            audio_lengths = []

        if images is not None:
            images_inputs = self.image_processor(images=images, **output_kwargs["images_kwargs"])
            image_grid_thw = images_inputs["image_grid_thw"]
        else:
            images_inputs = {}
            image_grid_thw = []

        if videos is not None:
            videos_inputs = self.video_processor(videos=videos, **output_kwargs["videos_kwargs"])
            videos_inputs["use_audio_in_video"] = use_audio_in_video

            # If user has not requested video metadata, pop it
            if "return_metadata" not in kwargs:
                video_metadata = videos_inputs.pop("video_metadata")
            else:
                video_metadata = videos_inputs["video_metadata"]
            video_grid_thw = videos_inputs["video_grid_thw"]
        else:
            videos_inputs = {}
            video_grid_thw = []
            video_metadata = []

        if not isinstance(text, list):
            text = [text]

        text = self.replace_multimodal_special_tokens(
            text,
            iter(audio_lengths),
            iter(image_grid_thw),
            iter(video_grid_thw),
            video_metadata=iter(video_metadata),
            audio_tokens_per_second=math.ceil(
                self.feature_extractor.sampling_rate / self.feature_extractor.hop_length / 2**downsample_times
            ),
            audio_timestamp_interval=audio_timestamp_interval,
            use_audio_in_video=iter(use_audio_in_video),
        )

        texts_inputs = self.tokenizer(text, **output_kwargs["text_kwargs"])

        return BatchFeature(
            data={
                **texts_inputs,
                **images_inputs,
                **videos_inputs,
                **audio_inputs,
            },
            tensor_type=kwargs.get("return_tensors"),
        )

    def replace_multimodal_special_tokens(
        self,
        text: list[str],
        audio_lengths: Iterator[int],
        image_grid_thw: Iterator[list[int]],
        video_grid_thw: Iterator[list[int]],
        video_metadata: Iterator[VideoMetadata],
        audio_tokens_per_second: int,
        audio_timestamp_interval: int,
        use_audio_in_video: Iterator[bool],
    ):
        # Extend mm token length
        merge_length_image = self.image_processor.merge_size**2

        processed_text = []
        for sample in text:
            special_tokens = self.mm_token_pattern.findall(sample)

            for special_token in special_tokens:
                if special_token == self.audio_token:
                    sample = sample.replace(
                        self.audio_token,
                        self._get_audio_tokens(
                            next(audio_lengths),
                            audio_tokens_per_second,
                            audio_timestamp_interval,
                        ),
                        1,
                    )
                elif special_token == self.image_token:
                    image_seq_length = next(image_grid_thw).prod() // merge_length_image
                    sample = sample.replace(self.image_token, "<|image_placeholder|>" * image_seq_length, 1)
                elif special_token == self.video_token:
                    metadata = next(video_metadata)
                    use_audio = next(use_audio_in_video)
                    if metadata.fps is None:
                        metadata.fps = 24
                    sample = sample.replace(
                        self.vision_bos_token + self.video_token + self.vision_eos_token,
                        self._get_video_tokens(
                            metadata.frames_indices,
                            metadata.fps,
                            next(video_grid_thw),
                            self.image_processor.merge_size,
                            audio_tokens_per_second if use_audio else None,
                            next(audio_lengths) if use_audio else None,
                        ),
                        1,
                    )

            sample = sample.replace("<|audio_placeholder|>", self.audio_token)
            sample = sample.replace("<|image_placeholder|>", self.image_token)
            sample = sample.replace("<|video_placeholder|>", self.video_token)
            processed_text.append(sample)
        return processed_text

    def _get_audio_tokens(self, audio_length: int, tokens_per_second: int, timestamp_interval: int):
        tokens_interval = tokens_per_second * timestamp_interval
        num_full_chunks = math.floor(audio_length / tokens_interval)
        num_residual_tokens = audio_length % tokens_interval

        audio_placeholders = ""
        for i in range(num_full_chunks):
            audio_placeholders += f"<{i * timestamp_interval:.1f} seconds>"
            audio_placeholders += "<|audio_placeholder|>" * tokens_interval
        if num_residual_tokens > 0:
            audio_placeholders += f"<{num_full_chunks * timestamp_interval:.1f} seconds>"
            audio_placeholders += "<|audio_placeholder|>" * num_residual_tokens
        return audio_placeholders

    def _get_video_tokens(
        self,
        indices: list[int] | np.ndarray,
        video_fps: float,
        video_grid_thw: list[int],
        merge_size: int = 2,
        audio_tokens_per_second: int | None = None,
        audio_length: int | None = None,
    ):
        # Copied from Qwen3VLProcessor::_calculate_timestamps
        if not isinstance(indices, list):
            indices = indices.tolist()
        if len(indices) % merge_size != 0:
            indices.extend(indices[-1] for _ in range(merge_size - len(indices) % merge_size))
        timestamps = [idx / video_fps for idx in indices]
        timestamps = [
            (timestamps[i] + timestamps[i + merge_size - 1]) / 2 for i in range(0, len(timestamps), merge_size)
        ]

        # Copied from Qwen3VLProcessor::__call__
        video_placeholders = []
        merge_length = merge_size**2
        frame_seqlen = video_grid_thw[1:].prod() // merge_length
        for frame_idx in range(video_grid_thw[0]):
            curr_time = timestamps[frame_idx]
            video_placeholder = ""
            video_placeholder += f"<{curr_time:.1f} seconds>"
            video_placeholder += self.vision_bos_token + "<|video_placeholder|>" * frame_seqlen + self.vision_eos_token
            video_placeholders.append(video_placeholder)

        # video with audio
        if audio_tokens_per_second:
            video_placeholders_with_audio = [self.audio_bos_token]
            video_second_per_chunk = indices[-1] / video_fps / video_grid_thw[0]
            audio_tokens = 0
            for i, video_chunk in enumerate(video_placeholders):
                if i == len(video_placeholders) - 1:
                    break
                audio_token = math.floor((i + 1) * video_second_per_chunk * audio_tokens_per_second) - math.floor(
                    i * video_second_per_chunk * audio_tokens_per_second
                )
                audio_token = min(audio_token, audio_length - audio_tokens)
                video_placeholders_with_audio.append(video_chunk + "<|audio_placeholder|>" * audio_token)
                audio_tokens += audio_token
            video_placeholders_with_audio.append(
                video_placeholders[-1] + "<|audio_placeholder|>" * (audio_length - audio_tokens)
            )
            video_placeholders_with_audio.append(self.audio_eos_token)
            video_placeholders = video_placeholders_with_audio
        return "".join(video_placeholders)

    @property
    def model_input_names(self):
        tokenizer_input_names = self.tokenizer.model_input_names
        feature_extractor_input_names = self.feature_extractor.model_input_names
        image_processor_input_names = self.image_processor.model_input_names
        return list(
            dict.fromkeys(
                tokenizer_input_names
                + feature_extractor_input_names
                + image_processor_input_names
                + ["feature_attention_mask"]
                + ["video_second_per_grid"]
            )
        )


__all__ = ["Qwen3_5OmniProcessor"]
